  "dz.hzd.abducao": "Meraklı uzaylılar hatıra olarak bir Bloop götürmek istiyor. Seçilme!",
  "dz.hzd.abelhas": "Biri kovanı kurcaladı! Kızgın bir sürü suçluyu arıyor. Vızzz!",
  "dz.hzd.acido": "Dokunduğu her şeyi eriten fokurdayan yeşil bir sümük. Iyy!",
  "dz.hzd.areia": "Her şeyi saklayan ve eşyaları fırlatan bir kum duvarı. Gözlerini kapat!",
  "dz.hzd.avalanche": "Dağdaki bütün kar bir anda inmeye karar verdi. Kartopları da hediye!",
  "dz.hzd.bolaneve": "Minik bir kartopuyla başladı... yokuş aşağı büyüdü, büyüdü, büyüdü!",
  "dz.hzd.bolhas": "Şehir büyüklüğünde bir köpük banyosu! Köpük, köpük, daha çok köpük.",
  "dz.hzd.boliche": "Bir dev bowling oynamaya geldi ve şehir pist oldu. Lobut sensin!",
  "dz.hzd.buraco": "Gökyüzünde her şeyi emen bir delik: kutular, çatılar ve dalgın Bloop'lar!",
  "dz.hzd.calor": "Güneş o kadar güçlü ki dondurmalar bile terliyor. Gölge bul!",
  "dz.hzd.chaolava": "Oyun ciddileşti: yer gerçekten lava döndü! Sadece yüksek yerler güvenli.",
  "dz.hzd.chocolate": "Çikolata fabrikası taştı! Çok lezzetli ama yüzmek için fazla yapışkan.",
  "dz.hzd.doces": "Rüya gibi ama her şeker bir buzdolabından ağır! Gölgelerden kaç.",
  "dz.hzd.enchente": "Yağmur, yağmur, daha çok yağmur! Su basamak basamak yükseliyor. İyi yüzenler avantajlı.",
  "dz.hzd.fantasma": "Siste kovalamaca oynamak isteyen minik hayaletler çıkıyor. Böö!",
  "dz.hzd.furacao": "Hortumun büyük kuzeni: iten rüzgâr, sel yapan yağmur ve ortada bir girdap.",
  "dz.hzd.geiser": "Yer fokurdar ve PUF! Aşağıdan sıcak su fışkırır.",
  "dz.hzd.geleia": "Biri dünyanın en büyük jölesini devirdi! Titriyor, sallanıyor ve her şeyi yutuyor.",
  "dz.hzd.gelo": "Donmuş gölde kaymak eğlenceliydi... buz çatlamaya başlayana kadar!",
  "dz.hzd.granizo": "Durmadan buz topları yağıyor. Küçük, hızlı ve çok sayıda!",
  "dz.hzd.gravidade": "Arada bir yerçekimi tatile çıkıyor ve her şey gökyüzüne uçuyor!",
  "dz.hzd.incendio": "Ateş yerde ve ağaçlarda ilerliyor. Yüksekte bekle ve yanmış topraktan geç.",
  "dz.hzd.lama": "O kadar yağmur yağdı ki tepe çamurdan bir kaydırak oldu, taşlar da hediye!",
  "dz.hzd.laser": "Uçan daireler şehri renkli lazerlerle tarıyor. Zıpla ya da eğil!",
  "dz.hzd.lua": "Uzay istasyonunda her şey süzülüyor: dev zıplayışlar ve her yerde kayan yıldızlar.",
  "dz.hzd.melancias": "Uçan bir meyve kamyonu yükünü düşürdü. Şap! Şap! Şap!",
  "dz.hzd.meteoro": "Büyüğü geliyor! Sadece yolun sonundaki sığınak dayanır. Koş!",
  "dz.hzd.meteoros": "Uzay taşları yağmur gibi yağıyor. Yerinde duranları hedef alıyorlar!",
  "dz.hzd.nevasca": "Burun donacak kadar soğuk! Bir kamp ateşi ya da sıcak bir ev bul.",
  "dz.hzd.pianos": "Tın, tın, GÜM! Gökten piyanolar düşüyor ve müzikli bir karmaşa bırakıyor.",
  "dz.hzd.pisao": "Dalgın bir dev şehirde dolaşıyor. Her adımı bir deprem!",
  "dz.hzd.raios": "Gök gürültüsü ve şimşek! En yüksek noktaya düşmeyi seviyorlar. Alçakta kal.",
  "dz.hzd.sumidouro": "Birden ortaya çıkıp büyüyen delikler. Yer İsviçre peynirine dönüyor!",
  "dz.hzd.terremoto": "Yer sallanıyor, çatlıyor ve binaları yıkıyor. Düşebilecek her şeyden uzak dur!",
  "dz.hzd.tornado": "Dışarıdakileri kovalayan ve çatıları koparan bir rüzgâr hunisi!",
  "dz.hzd.tsunami": "Deniz geri çekilir... ve her şeyle geri gelir! Her biri öncekinden büyük dev dalgalar.",
  "dz.hzd.vento": "Rüzgâr şehri toplamaya karar verdi... her şeyi yana savurarak!",
  "dz.hzd.vulcao": "Yanardağ huysuz uyandı: lav akıyor, ateş topları uçuyor.",
  "dz.hzt.abducao": "Uçan dairenin ışığından çık ya da bir çatının altında kal!",
  "dz.hzt.abelhas": "Sürüden kaç ve onları atlatmak için bir eve gir!",
  "dz.hzt.bolaneve": "Kocaman kartopları! Yükseğe çık ya da tam zamanında zıpla.",
  "dz.hzt.bolhas": "Köpük yükseliyor! Köpüklerde yüzebilirsin ama çok yükseliyor.",
  "dz.hzt.boliche": "Yuvarlanan toplar! Üstlerinden zıpla ya da yükseğe çık.",
  "dz.hzt.buraco": "Her şeyi ortaya çekiyor! Uzağa koş ya da bir eve gir.",
  "dz.hzt.calor": "Güneşten kaç! Gölgede ya da bir evin içinde kal.",
  "dz.hzt.chaolava": "Yere değme! Bir yüksek yerden diğerine zıpla.",
  "dz.hzt.chocolate": "Çikolata nehri yükseliyor! Yapışkan: yüzmek daha çok yorar.",
  "dz.hzt.doces": "Dev şekerler düşüyor! Renkli gölgelerden kaç.",
  "dz.hzt.fantasma": "Şakacı minik hayaletler! Onlardan kaç ya da ışıklı bir eve gir.",
  "dz.hzt.furacao": "Çok güçlü rüzgâr, yağmur ve hortum! Sığın ve sıkı tutun.",
  "dz.hzt.geiser": "Fokurdayan yerden çekil!",
  "dz.hzt.geleia": "Bir jöle dalgası! Yükseğe çık ve dalgaların arasında zıpla.",
  "dz.hzt.gelo": "Donmuş göl çatlıyor! Çatlaklardan uzağa kay.",
